function evaluatePostfix(postfix) {
    const stack = [];
    let errorPosition = -1;

    for (let i = 0; i < postfix.length; i++) {
        const token = postfix[i];

        if (typeof token === 'number') {
            stack.push(token);
        } else {
            if (stack.length < 2) {
                errorPosition = i;
                break;
            }
            const b = stack.pop();
            const a = stack.pop();
            const result = applyOp(a, b, token);
            stack.push(result);
        }
    }

    if (errorPosition !== -1) {
        throw new Error(`Syntax error at position ${errorPosition}`);
    }

    if (stack.length !== 1) {
        throw new Error(`Syntax error at position ${postfix.length}`);
    }

    return stack.pop();
}

