  solve(b) {
    if (!Array.isArray(b) || b.length !== this.rows.length) {
      throw new Error("b has the wrong length");
    }

    const n = this.rows.length;
    const augmentedMatrix = this.rows.map((row, i) => [...row, b[i]]);

    // Gaussian elimination
    for (let i = 0; i < n; i++) {
      // Find the pivot row
      let maxRow = i;
      for (let j = i + 1; j < n; j++) {
        if (Math.abs(augmentedMatrix[j][i]) > Math.abs(augmentedMatrix[maxRow][i])) {
          maxRow = j;
        }
      }

      // Swap rows
      [augmentedMatrix[i], augmentedMatrix[maxRow]] = [augmentedMatrix[maxRow], augmentedMatrix[i]];

      // Make the pivot element 1
      const pivot = augmentedMatrix[i][i];
      for (let j = i; j <= n; j++) {
        augmentedMatrix[i][j] /= pivot;
      }

      // Eliminate other rows
      for (let j = 0; j < n; j++) {
        if (i !== j) {
          const factor = augmentedMatrix[j][i];
          for (let k = i; k <= n; k++) {
            augmentedMatrix[j][k] -= factor * augmentedMatrix[i][k];
          }
        }
      }
    }

    // Extract the solution
    const result = [];
    for (let i = 0; i < n; i++) {
      result.push(augmentedMatrix[i][n]);
    }

    return result;
  }
}

