def status_counts(entries):
    counts = {}
    for entry in entries:
        status = entry['status']
        if status in counts:
            counts[status] += 1
        else:
            counts[status] = 1
    return counts

def top_paths(entries, n=3):
    path_counts = {}
    for entry in entries:
        path = entry['path']
        if path in path_counts:
            path_counts[path] += 1
        else:
            path_counts[path] = 1
    sorted_paths = sorted(path_counts.items(), key=lambda item: item[1], reverse=True)
    return sorted_paths[:n]

