        line = "2023-10-01 12:34:56,GET,/path,200"
        expected = {
            'timestamp': "2023-10-01 12:34:56",
            'method': "GET",
            'path': "/path",
            'status': 200
        }
        self.assertEqual(parse_line(line), expected)

